from itertools import combinations
objs=[A,B,C,D]
def pad(a,H,W,align='tl'):
 out=np.zeros((H,W),int)
 y=(H-a.shape[0])//2 if align=='center' else 0; x=(W-a.shape[1])//2 if align=='center' else 0
 out[y:y+a.shape[0],x:x+a.shape[1]]=a
 return out
for al in ['tl','center']:
 H=max(a.shape[0] for a in objs); W=max(a.shape[1] for a in objs)
 xx=[pad(a,H,W,al) for a in objs]
 for n in range(2,5):
  for ix in combinations(range(4),n):
   arr=[xx[i] for i in ix]
   for op in ['xor','or','and']:
    z=arr[0].copy()
    for a in arr[1:]: z= (z^a) if op=='xor' else ((z|a) if op=='or' else (z&a))
    # crop nonzero bbox compare
    ys,xs=np.where(z); 
    if len(ys): zcrop=z[ys.min():ys.max()+1,xs.min():xs.max()+1]
    else: zcrop=z
    if zcrop.shape==O.shape and np.array_equal(zcrop,O):print('match',al,ix,op)

